export { MOTION_DURATION, MOTION_EASE, MOTION_DISTANCE, MOTION_SPRING } from "./tokens";
export {
  transitionInstant,
  transitionFast,
  transitionStandard,
  transitionSlow,
  transitionEnter,
  transitionExit,
  springGentle,
  springSnappy,
} from "./transitions";
export { fadeIn, scaleIn, scaleInDown, scaleInVertical, slideInUp } from "./variants";
export { staggerContainer } from "./orchestration";

/**
 * Kikito CN — helpers de orquestração (sequenciar entrada de filhos). Pensado
 * pra portar o padrão `staggerChildren` visto em vários arquivos de
 * docs/component-import/animation-backport/PLAN.md (animated-table,
 * animated-list) sem reescrever a lógica de stagger a cada componente novo.
 */
import type { Variants } from "motion/react";

/**
 * Variants pro elemento PAI de uma lista — cada filho precisa ter sua própria
 * `Variants` de entrada (ex. `fadeIn`/`slideInUp` de ./variants) com
 * `initial`/`animate` compatíveis; o pai só controla o *timing* entre eles.
 */
export function staggerContainer(staggerDelay = 0.05, delayChildren = 0): Variants {
  return {
    initial: {},
    animate: { transition: { staggerChildren: staggerDelay, delayChildren } },
    exit: { transition: { staggerChildren: staggerDelay / 2, staggerDirection: -1 } },
  };
}

/**
 * Kikito CN — tokens de animação (camada 2, espelha `--ks-motion-*` em
 * `src/styles/kikitocn-tokens.css`). Fonte única de duração/easing/spring
 * pra qualquer componente que use `motion` — nunca número mágico solto.
 *
 * Valores ancorados em uso real, não inventados (ver
 * docs/component-import/motion-infrastructure/PLAN.md): 150ms/200ms/80ms
 * são os 3 valores de duração mais frequentes já em produção em
 * src/components/ui/cn/**, e os springs `gentle`/`snappy` foram colhidos
 * de `Modal.tsx`/`Select.tsx`, que já usavam esses dois presets ad-hoc
 * antes deste sistema existir.
 */

/** Segundos — prop `duration` do `motion` espera número em segundos, não string CSS. */
export const MOTION_DURATION = {
  instant: 0.08,
  fast: 0.15,
  standard: 0.2,
  slow: 0.3,
  slower: 0.5,
} as const;

export const MOTION_EASE = {
  standard: [0.22, 1, 0.36, 1],
  decelerate: [0, 0, 0.2, 1],
  accelerate: [0.4, 0, 1, 1],
} as const;

/** Pixels — distância de deslocamento em variantes de entrada/saída (slide-in/slide-up). */
export const MOTION_DISTANCE = { sm: 8, md: 16, lg: 24 } as const;

export const MOTION_SPRING = {
  gentle: { stiffness: 150, damping: 25 }, // Modal — elementos maiores/mais pesados
  snappy: { stiffness: 350, damping: 25 }, // Select — elementos menores/mais rápidos
} as const;

/**
 * Kikito CN — presets de `Transition` do `motion`, nomeados em vez de
 * `{ duration: 0.2 }` solto repetido em cada componente. Ver ./tokens.ts
 * pra origem dos números.
 */
import type { Transition } from "motion/react";

import { MOTION_DURATION, MOTION_EASE, MOTION_SPRING } from "./tokens";

export const transitionInstant: Transition = { duration: MOTION_DURATION.instant, ease: MOTION_EASE.standard };
export const transitionFast: Transition = { duration: MOTION_DURATION.fast, ease: MOTION_EASE.standard };
export const transitionStandard: Transition = { duration: MOTION_DURATION.standard, ease: MOTION_EASE.standard };
export const transitionSlow: Transition = { duration: MOTION_DURATION.slow, ease: MOTION_EASE.standard };

/** Entrada (decelera até parar) e saída (acelera até sumir) — pra AnimatePresence com curvas assimétricas. */
export const transitionEnter: Transition = { duration: MOTION_DURATION.standard, ease: MOTION_EASE.decelerate };
export const transitionExit: Transition = { duration: MOTION_DURATION.fast, ease: MOTION_EASE.accelerate };

/** Springs — colhidos de Modal.tsx (gentle) e Select.tsx (snappy), ver ./tokens.ts. */
export const springGentle: Transition = { type: "spring", ...MOTION_SPRING.gentle };
export const springSnappy: Transition = { type: "spring", ...MOTION_SPRING.snappy };

/**
 * Kikito CN — vocabulário próprio de variantes de animação (`Variants` do
 * `motion`). Em vez de cada componente inventar seu `initial`/`animate`/
 * `exit`, importa um preset nomeado daqui — é isto que vira "nosso" de
 * verdade, não um detalhe de implementação escondido em cada componente.
 *
 * Se um padrão novo aparecer (ex. ao portar um item de
 * docs/component-import/animation-backport/PLAN.md) e nenhum preset daqui
 * servir, adicionar aqui primeiro, depois consumir — é assim que o
 * vocabulário cresce organizado em vez de fragmentar de novo.
 */
import type { Variants } from "motion/react";

import { MOTION_DISTANCE } from "./tokens";

/** Fade puro — sem deslocamento nem escala. Ex.: backdrop de overlay. */
export const fadeIn: Variants = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  exit: { opacity: 0 },
};

/** Escala uniforme a partir do centro — menus/dropdowns que "brotam" do trigger (padrão DropdownMenu). */
export const scaleIn: Variants = {
  initial: { opacity: 0, scale: 0.95 },
  animate: { opacity: 1, scale: 1 },
  exit: { opacity: 0, scale: 0.95 },
};

/** Escala + desliza a partir de cima — painéis maiores (padrão Modal, distância = --ks-motion-distance-md). */
export const scaleInDown: Variants = {
  initial: { opacity: 0, scale: 0.92, y: -MOTION_DISTANCE.md },
  animate: { opacity: 1, scale: 1, y: 0 },
  exit: { opacity: 0, scale: 0.92, y: -MOTION_DISTANCE.md },
};

/** Escala só no eixo vertical (sem translate) — painéis que "desenrolam" de cima pra baixo (padrão Select). */
export const scaleInVertical: Variants = {
  initial: { opacity: 0, scaleY: 0.9 },
  animate: { opacity: 1, scaleY: 1 },
  exit: { opacity: 0, scaleY: 0.9 },
};

/** Desliza a partir de baixo, sem escala — listas/toasts entrando de baixo pra cima. */
export const slideInUp: Variants = {
  initial: { opacity: 0, y: MOTION_DISTANCE.sm },
  animate: { opacity: 1, y: 0 },
  exit: { opacity: 0, y: MOTION_DISTANCE.sm },
};
